const countries = [
  { name: "Eritrea", code: "+291", flag: "🇪🇷" },
  { name: "Ethiopia", code: "+251", flag: "🇪🇹" },
  { name: "Sudan", code: "+249", flag: "🇸🇩" },
  { name: "Kenya", code: "+254", flag: "🇰🇪" }
];

export default function DEWLPage({ language }: { language: Language }) {
  const router = useRouter();
  const t = translations[language];

  const [country, setCountry] = useState(countries[0]);
const [number, setNumber] = useState("");
const [notice, setNotice] = useState("");

  function changeLanguage(value: Language) {
    const routes = { en: "/", ti: "/ti", am: "/am" };
    router.push(routes[value]);
  }

  function pressDigit(digit: string) {
    setNumber((current) => current + digit);
  }

  function handleCall() {
    if (!number.trim()) {
      setNotice(
        language === "ti"
          ? "በጃኹም ቁጽሪ ስልኪ ኣእትዉ።"
          : language === "am"
          ? "እባክዎ ስልክ ቁጥር ያስገቡ።"
          : "Please enter a phone number."
      );
      return;
    }

    setNotice(t.callNote);
  }

  return (
    <main className="dewl-app">
      <header className="site-header">
        <a href="/" className="brand">
          <span className="brand-mark"><Phone size={22} /></span>
          <span>DEWL</span>
        </a>

        <nav className="main-nav">
          <a href="/"><Home size={15} /> {t.home}</a>
          <a href="#rates"><Wallet size={15} /> {t.rates}</a>
          <a href="#features"><Globe2 size={15} /> {t.how}</a>
          <a href="#faq"><CircleHelp size={15} /> {t.faq}</a>
          <a href="#contact">{t.contact}</a>
        </nav>

        <div className="header-actions">
          <select
            aria-label={t.selectLanguage}
            value={language}
            onChange={(event) => changeLanguage(event.target.value as Language)}
            className="language-select"
          >
            <option value="en">English</option>
            <option value="ti">ትግርኛ</option>
            <option value="am">አማርኛ</option>
          </select>
          <a href="#account" className="account-button">
            <User size={16} /> {t.account}
          </a>
        </div>
      </header>

      <section className="hero-banner">
        <div className="hero-content">
          <span className="hero-eyebrow">DEWL · CALL HOME</span>
          <h1>{t.heroTitle}</h1>
          <p>{t.heroText}</p>
          <a href="#dialer" className="hero-button">
            {t.start} <ArrowRight size={17} />
          </a>
        </div>
        <div className="hero-flag">🇪🇷</div>
      </section>

      <section className="dashboard-grid">
        <aside className="dashboard-panel account-panel" id="account">
          <div className="panel-heading">
            <div className="panel-icon"><Wallet size={19} /></div>
            <h2>{t.welcome}</h2>
          </div>

          <p className="muted">{t.balance}</p>
          <div className="balance-amount">€12.50</div>
          <span className="demo-label">{t.demo}</span>

          <button
            className="primary-outline-button"
            onClick={() => setNotice(t.accountNote)}
          >
            <Plus size={17} /> {t.addCredit}
          </button>

          <p className="small-note">{t.accountNote}</p>

          <div className="panel-divider" />

          <div className="rates-heading" id="rates">
            <h3>{t.ourRates}</h3>
            <span>🇪🇷</span>
          </div>
          <div className="rate-row">
            <span>{t.mobile}</span>
            <strong>{t.comingSoon}</strong>
          </div>
          <div className="rate-row">
            <span>{t.landline}</span>
            <strong>{t.comingSoon}</strong>
          </div>
          <p className="small-note">{t.ratesNote}</p>

          <a href="#rates" className="text-link">
            {t.rates} <ArrowRight size={14} />
          </a>
        </aside>

        <section className="dashboard-panel dialer-panel" id="dialer">
          <div className="panel-heading">
            <div className="panel-icon green-icon"><Phone size={19} /></div>
            <h2>{t.makeCall}</h2>
          </div>

          <label className="field-label">{t.destination}</label>
          <div className="country-select-wrap">
            <select
              className="country-select"
              value={country.name}
              onChange={(event) => {
                const selected = countries.find((item) => item.name === event.target.value);
                if (selected) setCountry(selected);
              }}
            >
              {countries.map((item) => (
                <option key={item.name} value={item.name}>
                  {item.flag} {t.destinations[item.name as keyof typeof t.destinations]}
                </option>
              ))}
            </select>
            <ChevronDown size={17} />
          </div>

          <label className="field-label">{t.phoneNumber}</label>
          <div className="phone-input-wrap">
            <span className="country-code">{country.code}</span>
            <input
              value={number}
              onChange={(event) => setNumber(event.target.value)}
              placeholder={t.enterNumber}
              inputMode="tel"
            />
          </div>

          <div className="dial-pad">
            {["1", "2", "3", "4", "5", "6", "7", "8", "9", "*", "0", "#"].map((digit) => (
              <button key={digit} onClick={() => pressDigit(digit)}>
                {digit}
              </button>
            ))}
          </div>

          <button className="call-button" onClick={handleCall}>
            <Phone size={19} /> {t.call}
          </button>

          {notice && <p className="call-notice" role="status">{notice}</p>}
          <p className="small-note">{t.callNote}</p>
        </section>

        <aside className="dashboard-panel active-call-panel">
          <div className="panel-heading">
            <div className="panel-icon"><Headphones size={19} /></div>
            <h2>{t.activeCall}</h2>
          </div>

          <div className="call-status-circle">
            <Phone size={30} />
          </div>
          <h3 className="no-call-title">{t.noActiveCall}</h3>
          <p className="muted call-preview-text">{t.callPreview}</p>

          <div className="call-controls">
            <button disabled><Mic size={19} /><span>{t.mute}</span></button>
            <button disabled><Grid3X3 size={19} /><span>{t.keypad}</span></button>
            <button disabled><Volume2 size={19} /><span>{t.speaker}</span></button>
          </div>

          <button className="end-call-button" disabled>
            <PhoneOff size={18} /> {t.end}
          </button>
          <p className="small-note">{t.demo} · {t.callNote}</p>
        </aside>
      </section>

      <section className="feature-strip" id="features">
        <div className="feature-item">
          <Zap size={23} />
          <div><strong>{t.simple}</strong><p>{t.simpleText}</p></div>
        </div>
        <div className="feature-item">
          <ShieldCheck size={23} />
          <div><strong>{t.secure}</strong><p>{t.secureText}</p></div>
        </div>
        <div className="feature-item">
          <Globe2 size={23} />
          <div><strong>{t.international}</strong><p>{t.internationalText}</p></div>
        </div>
        <div className="feature-item">
          <CreditCard size={23} />
          <div><strong>{t.prepaid}</strong><p>{t.prepaidText}</p></div>
        </div>
      </section>

      <footer className="site-footer" id="contact">
        <span>© 2026 DEWL. {t.rights}</span>
        <strong>{t.slogan}</strong>
        <span>English · ትግርኛ · አማርኛ</span>
        <a href="mailto:support@dewl.com">
          {t.contact} <ArrowRight size={13} />
        </a>
      </footer>
    </main>
  );
}
